    mutationFn: (f: { pool: string; personId: number | null; memberPool: string | null; share: string; from: string; to: string }) =>
      postJson<{ pools: Pool[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/pools/members`, f),
    onSuccess: async () => {
      setMember('');
      setShare('');
      setFrom('');
      setTo('');
      await queryClient.invalidateQueries({ queryKey: poolsKey(sheetId) });
    },
  });

  return (
    <div data-testid={`pool-row-${pool.name}`}>
      <strong data-testid="pool-name">{pool.name}</strong>{' '}
      Total <span data-testid="pool-total-share">{fig(pool.totalShare)}</span>{' '}
      Balanced <span data-testid="pool-balanced">{pool.balanced ? 'yes' : 'no'}</span>
      <ul>
        {pool.members.map((m) => (
          <li
            key={m.pool === null ? m.personId : `pool:${m.pool}`}
            data-testid={m.pool === null ? `pool-member-${pool.name}-${m.personId}` : `pool-member-${pool.name}-pool-${m.pool}`}
          >
            <span data-testid="pool-member-name">{m.name}</span>{' '}
            <span data-testid="pool-share">{fig(m.share)}</span>{' '}
            <span data-testid="pool-cut">{fig(m.cut ?? '')}</span>
            {Object.entries(m.periodCuts ?? {}).map(([period, cut]) => (
              <span key={period}>
                {' '}
                {period} <span data-testid={`pool-cut-${period}`}>{fig(cut ?? '')}</span>
              </span>
            ))}
            {(m.from !== null || m.to !== null) && ` (${m.from ?? ''} – ${m.to ?? ''})`}
            {m.retired && ' (retired)'}
          </li>
        ))}
      </ul>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          submitOnce(() => {
            add.reset();
            const memberPool = member.startsWith('pool:') ? member.slice('pool:'.length) : null;
            const personId = member === '' || memberPool !== null ? null : Number(member);
            return add.mutateAsync({ pool: pool.name, personId, memberPool, share, from: from.trim(), to: to.trim() });
          });
        }}
      >
        <select
          data-testid="pool-member-select"
          value={member}
          onChange={(e: ChangeEvent<HTMLSelectElement>) => {
            setMember(e.target.value);
            add.reset();
          }}
        >
          <option value="">Choose a person or pool</option>
          {people.map((p) => (
            <option key={p.id} value={String(p.id)}>
              {p.name}
            </option>
          ))}
          {pools.map((p) => (
            <option key={`pool:${p.name}`} value={`pool:${p.name}`}>
              {`pool:${p.name}`}
            </option>
          ))}
        </select>{' '}
        <label>
          Share{' '}
          <input
            data-testid="pool-member-share"
            inputMode="decimal"
            value={share}
            onChange={(e) => {
              setShare(e.target.value);
              add.reset();
            }}
          />
        </label>{' '}
        <input
          placeholder="from yyyy-mm-dd"
          data-testid="pool-member-from"
          value={from}
          onChange={(e) => {
            setFrom(e.target.value);
            add.reset();
          }}
        />{' '}
        <input
          placeholder="to yyyy-mm-dd"
          data-testid="pool-member-to"
          value={to}
          onChange={(e) => {
            setTo(e.target.value);
            add.reset();
          }}
        />{' '}
        <button type="submit" data-testid="pool-member-add" disabled={add.isPending}>
          Add member
        </button>
      </form>
      {add.isError && <p data-testid="pool-error">{add.error.message}</p>}
    </div>
  );
}

/** The sheet's pools: a form that adds one (a name, unique on the sheet) and each pool with its members. */
function Pools({ sheetId }: { sheetId: string }) {
  const pools = usePools(sheetId);
  const people = usePeople(sheetId);
  const queryClient = useQueryClient();
  const [name, setName] = useState('');

  const submitOnce = useSingleFlight();
  const save = useMutation({
    mutationFn: (f: { name: string }) =>
      postJson<{ pools: Pool[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/pools`, f),
    onSuccess: async () => {
      setName('');
      await queryClient.invalidateQueries({ queryKey: poolsKey(sheetId) });
    },
  });

  return (
    <section data-testid="pools">
      <form
        data-testid="pool-form"
        onSubmit={(e) => {
          e.preventDefault();
          submitOnce(() => {
            save.reset();
            return save.mutateAsync({ name });
          });
        }}
      >
        <label>
          Pool{' '}
          <input
            data-testid="pool-form-name"
            value={name}
            onChange={(e) => {
              setName(e.target.value);
              save.reset();
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="pool-form-submit" disabled={save.isPending}>
          Add pool
        </button>
        {save.isError && <p data-testid="pool-form-error">{save.error.message}</p>}
      </form>
      {(pools.data ?? []).map((p) => (
        <PoolRow key={p.name} sheetId={sheetId} pool={p} pools={pools.data ?? []} people={people.data ?? []} />
      ))}
      {pools.isError && <p data-testid="pools-error">{pools.error.message}</p>}
    </section>
  );
}

export const contribution = SheetBody.fill({ order: 7, Component: ({ sheetId }) => <Pools sheetId={sheetId} /> });
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A member of a pool: a person (by id, and their name now) or another pool (`pool`, its name; `personId` then
 *  null), their share percent (two decimals), whether they are retired (a person with a retirement date set,
 *  whatever the date: they get no cut, their share spread over the others, but it counts in the total share) and their cut of the pool's pot (two decimals; null when
 *  the pool is not balanced, has no pot or has only retired members: a pool that is a member of another has its cut there as its pot; null
 *  too for a member that is not current), the membership's from-date and to-date (null when not given) and whether
 *  they include the sheet's today (a member that is not current counts in neither the total share nor the balance), and,
 *  for every period whose to-date is on or before the sheet's today, by period name in from-date order, their cut as it
 *  stood at the end of that period (null when they had none then). */
export type PoolMember = {
  personId: number | null;
  pool: string | null;
  name: string;
  share: string;
  retired: boolean;
  cut: string | null;
  from: string | null;
  to: string | null;
  current: boolean;
  periodCuts: Record<string, string | null>;
};

/** A pool: its name, its members in the order they were added, the total of their shares (two decimals),
 *  whether that total is exactly 100.00 and its place in the order the sheet's pools were added (0 for the first). */
export type Pool = { name: string; members: PoolMember[]; totalShare: string; balanced: boolean; added: number };

export function poolsKey(sheetId: string) {
  return ['sheet', sheetId, 'pools'];
}

/** The sheet's pools, by name. */
export function usePools(sheetId: string) {
  return useQuery({
    queryKey: poolsKey(sheetId),
    queryFn: async () => (await getJson<{ pools: Pool[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/pools`)).pools,
  });
}
