package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Hold;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.settings.SettingsRepository;
import org.springframework.stereotype.Service;

/** Close an open period: fix its due-total as shown now (the dues now, late charges included, of the claims whose
 *  due-by falls in it that count by the status they had at the end of its last day, a person's open (OPEN or PENDING) claims dated
 *  within one of their holds left out unless bound by a statement, skipping those with none), so later changes to
 *  rates do not alter it; and each person's due-total for it likewise, for every person on the sheet (0.00 for one
 *  with nothing in it), and each person's carried figure for it (their claims that count whose due-by falls in a
 *  period ending before it starts and that were still OPEN or PENDING at the end of its last day, plus their opening
 *  balance for it, 0.00 for one with none). Writes PERIOD_CLOSED, ending auto=yes when closed by the sheet's grace days. */
@Service
public class PeriodCloser {

    private final PeriodRepository periods;
    private final ClaimRepository claims;
    private final PersonRepository people;
    private final SettingsRepository settings;
    private final Audit audit;

    public PeriodCloser(PeriodRepository periods, ClaimRepository claims, PersonRepository people,
            SettingsRepository settings, Audit audit) {
        this.periods = periods;
        this.claims = claims;
        this.people = people;
        this.settings = settings;
        this.audit = audit;
    }

    public Period close(String sheetId, String by, Period found, boolean auto) {
        return close(sheetId, by, found, auto, false);
    }

    /** Close, or soft-close, a period (open or soft-closed), fixing its figures afresh. A soft close writes
     *  PERIOD_SOFT_CLOSED instead of PERIOD_CLOSED. */
    public Period close(String sheetId, String by, Period found, boolean auto, boolean soft) {
        LocalDate from = LocalDate.parse(found.from());
        LocalDate to = LocalDate.parse(found.to());
        String today = periods.today(sheetId);
        Map<Long, List<Hold>> holds = new java.util.HashMap<>();
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        Map<Long, BigDecimal> personTotals = new LinkedHashMap<>();
        Map<Long, BigDecimal> personCarried = new LinkedHashMap<>();
        List<Period> earlier = periods.list(sheetId).stream().filter(q -> LocalDate.parse(q.to()).isBefore(from)).toList();
        for (Person p : people.list(sheetId)) {
            personTotals.put(p.id(), BigDecimal.ZERO.setScale(2));
            personCarried.put(p.id(), BigDecimal.ZERO.setScale(2));
            holds.put(p.id(), p.liveHolds(today));
        }
        Map<Long, String> statusesThen = claims.statusesOn(sheetId, to);
        for (Claim c : claims.list(sheetId)) {
            String then = statusesThen.get(c.id());
            if (!c.countsAs(then, holds.getOrDefault(c.personId(), List.of()), today)) continue;
            LocalDate on = LocalDate.parse(c.dueBy());
            boolean in = !on.isBefore(from) && !on.isAfter(to);
            boolean carried = (then.equals("OPEN") || then.equals("PENDING")) && earlier.stream()
                    .anyMatch(q -> !on.isBefore(LocalDate.parse(q.from())) && !on.isAfter(LocalDate.parse(q.to())));
            if (!in && !carried) continue;
            BigDecimal now = claims.dueNow(sheetId, c);
            if (now == null) continue;
            if (in) {
                total = total.add(now);
                personTotals.merge(c.personId(), now, BigDecimal::add);
            }
            if (carried) personCarried.merge(c.personId(), now, BigDecimal::add);
        }
        Map<Long, BigDecimal> openings = periods.openings(sheetId, found.id());
        for (Map.Entry<Long, BigDecimal> e : openings.entrySet()) {
            if (personCarried.containsKey(e.getKey())) personCarried.merge(e.getKey(), e.getValue(), BigDecimal::add);
        }
        String shown = total.setScale(2).toPlainString();
        periods.close(sheetId, found.id(), total, personTotals, personCarried, soft);
        audit.record((soft ? "PERIOD_SOFT_CLOSED" : "PERIOD_CLOSED") + " sheet=" + sheetId + " by=" + by + " period=" + found.name() + " total=" + shown
                + (auto ? " auto=yes" : ""));
        return new Period(found.id(), found.name(), found.from(), found.to(), !soft, shown, personTotals.entrySet().stream().collect(Collectors.toMap(e -> Long.toString(e.getKey()),
                e -> e.getValue().setScale(2).toPlainString(), (a, b) -> a, LinkedHashMap::new)), personCarried.entrySet().stream().collect(Collectors.toMap(e -> Long.toString(e.getKey()),
                e -> e.getValue().setScale(2).toPlainString(), (a, b) -> a, LinkedHashMap::new)), soft, found.cap(),
                openings.entrySet().stream().collect(Collectors.toMap(e -> Long.toString(e.getKey()),
                e -> e.getValue().setScale(2).toPlainString(), (a, b) -> a, LinkedHashMap::new)), found.locked());
    }

    /** Close, by the sheet's grace days (none when blank), every open (not closed nor soft-closed) period whose to-date plus the grace days is
     *  before the sheet's today, in order of their to-dates. */
    public void closeLapsed(String sheetId, String by, LocalDate today) {
        Integer grace = settings.graceDays(sheetId);
        if (grace == null) return;
        List<Period> lapsed = periods.list(sheetId).stream()
                .filter(p -> !p.closed() && !p.softClosed() && LocalDate.parse(p.to()).plusDays(grace).isBefore(today))
                .sorted(Comparator.comparing(Period::to)).toList();
        for (Period p : lapsed) close(sheetId, by, p, true);
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.settings.SettingsRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

/** Close a period, by a role the sheet's permission matrix allows (by default a clerk or a steward), with
 *  {@link PeriodCloser}: fix its due-total as shown now (the dues now, late charges included, of the claims whose due-by falls in it that count by
 *  the status they had at the end of its last day, a person's
 *  open (OPEN or PENDING) claims dated within one of their holds left out unless bound by a statement,
 *  skipping those with none), so later changes to rates do not alter it; and each person's due-total for it
 *  likewise, for every person on the sheet (0.00 for one with nothing in it). */
public class ClosePeriod {
    public void close(@PathVariable("sheetId") String sheetId, @PathVariable("periodName") String periodName,
            ServerHttpConnection connection, PeriodRepository repository, SettingsRepository settings,
            PeriodCloser closer, Out<Period> period) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        if (!repository.lockSheet(id)) {
            throw new BadRequestException("no such sheet");
        }
        Period found = repository.find(id, periodName == null ? "" : periodName.trim());
        if (found == null) {
            throw new BadRequestException("no such period");
        }
        if (!settings.allows(id, "close", by)) {
            throw new BadRequestException("a " + settings.role(id, by) + " cannot close a period");
        }
        if (found.closed()) {
            throw new BadRequestException("the period " + found.name() + " is already closed");
        }
        period.set(closer.close(id, by, found, false));
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.settings.SettingsRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

/** Soft-close an open period, by a role the sheet's permission matrix allows to close one, with {@link PeriodCloser}:
 *  its due-total and each person's due-total for it are fixed as a close fixes them, but claims whose due-by falls
 *  inside it can still be added, edited, opened, settled and voided. A closed or soft-closed period cannot be soft-closed. */
public class SoftClosePeriod {
    public void softClose(@PathVariable("sheetId") String sheetId, @PathVariable("periodName") String periodName,
            ServerHttpConnection connection, PeriodRepository repository, SettingsRepository settings,
            PeriodCloser closer, Out<Period> period) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        if (!repository.lockSheet(id)) {
            throw new BadRequestException("no such sheet");
        }
        Period found = repository.find(id, periodName == null ? "" : periodName.trim());
        if (found == null) {
            throw new BadRequestException("no such period");
        }
        if (!settings.allows(id, "close", by)) {
            throw new BadRequestException("a " + settings.role(id, by) + " cannot close a period");
        }
        if (found.closed()) {
            throw new BadRequestException("the period " + found.name() + " is already closed");
        }
        if (found.softClosed()) {
            throw new BadRequestException("the period " + found.name() + " is already soft-closed");
        }
        period.set(closer.close(id, by, found, false, true));
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.settings.SettingsRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

/** Reopen a closed or soft-closed period, by a role the sheet's permission matrix allows (by default a steward only): its fixed due-total is dropped, so it totals the
 *  claims in it live again (bound ones at their bound figure). */
public class ReopenPeriod {
    public void reopen(@PathVariable("sheetId") String sheetId, @PathVariable("periodName") String periodName,
            ServerHttpConnection connection, PeriodRepository repository, SettingsRepository settings, Audit audit,
            Out<Period> period) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        if (!repository.lockSheet(id)) {
            throw new BadRequestException("no such sheet");
        }
        Period found = repository.find(id, periodName == null ? "" : periodName.trim());
        if (found == null) {
            throw new BadRequestException("no such period");
        }
        if (!settings.allows(id, "reopen", by)) {
            throw new BadRequestException("a " + settings.role(id, by) + " cannot reopen a period");
        }
        if (found.locked()) {
            throw new BadRequestException("the period " + found.name() + " is locked");
        }
        if (!found.closed() && !found.softClosed()) {
            throw new BadRequestException("the period " + found.name() + " is not closed");
        }
        repository.reopen(id, found.id());
        audit.record("PERIOD_REOPENED sheet=" + id + " by=" + by + " period=" + found.name());
        period.set(new Period(found.id(), found.name(), found.from(), found.to(), false, null, java.util.Map.of(), java.util.Map.of(), false, found.cap(),
                repository.list(id).stream().filter(p -> p.id() == found.id()).findFirst().map(Period::personOpenings).orElse(java.util.Map.of()), false));
    }
}
# Close a period (open or soft-closed): fix its due-total as it is now. A closed period cannot be closed again.
guard:
  class: net.officefloor.hq.app.settings.RefuseViewer
  next: close
close:
  class: net.officefloor.hq.app.period.ClosePeriod
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithPeriod
# Lock a period (a steward only): a locked period cannot be reopened. Locking a locked period is refused.
guard:
  class: net.officefloor.hq.app.settings.RefuseViewer
  next: lock
lock:
  class: net.officefloor.hq.app.period.LockPeriod
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithPeriod
# Reopen a closed period (a steward only): its due-total is live again.
guard:
  class: net.officefloor.hq.app.settings.RefuseViewer
  next: reopen
reopen:
  class: net.officefloor.hq.app.period.ReopenPeriod
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithPeriod
# Soft-close a period: fix its due-total as it is now, while claims dated in it can still be changed.
guard:
  class: net.officefloor.hq.app.settings.RefuseViewer
  next: softClose
softClose:
  class: net.officefloor.hq.app.period.SoftClosePeriod
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithPeriod
# Unlock a locked period (a steward only). Unlocking an unlocked period is refused.
guard:
  class: net.officefloor.hq.app.settings.RefuseViewer
  next: unlock
unlock:
  class: net.officefloor.hq.app.period.UnlockPeriod
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithPeriod

