 *  inside it can still be added, edited, opened, settled and voided. A closed or soft-closed period cannot be soft-closed. */
public class SoftClosePeriod {
    public void softClose(@PathVariable("sheetId") String sheetId, @PathVariable("periodName") String periodName,
            ServerHttpConnection connection, PeriodRepository repository, SettingsRepository settings,
            PeriodCloser closer, Out<Period> period) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        if (!repository.lockSheet(id)) {
            throw new BadRequestException("no such sheet");
        }
        Period found = repository.find(id, periodName == null ? "" : periodName.trim());
        if (found == null) {
            throw new BadRequestException("no such period");
        }
        if (!settings.allows(id, "close", by)) {
            throw new BadRequestException("a " + settings.role(id, by) + " cannot close a period");
        }
        if (found.closed()) {
            throw new BadRequestException("the period " + found.name() + " is already closed");
        }
        if (found.softClosed()) {
            throw new BadRequestException("the period " + found.name() + " is already soft-closed");
        }
        period.set(closer.close(id, by, found, false, true));
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.settings.SettingsRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

/** Reopen a closed or soft-closed period, by a role the sheet's permission matrix allows (by default a steward only): its fixed due-total is dropped, so it totals the
 *  claims in it live again (bound ones at their bound figure). */
public class ReopenPeriod {
    public void reopen(@PathVariable("sheetId") String sheetId, @PathVariable("periodName") String periodName,
            ServerHttpConnection connection, PeriodRepository repository, SettingsRepository settings, Audit audit,
            Out<Period> period) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        if (!repository.lockSheet(id)) {
            throw new BadRequestException("no such sheet");
        }
        Period found = repository.find(id, periodName == null ? "" : periodName.trim());
        if (found == null) {
            throw new BadRequestException("no such period");
        }
        if (!settings.allows(id, "reopen", by)) {
            throw new BadRequestException("a " + settings.role(id, by) + " cannot reopen a period");
        }
        if (found.locked()) {
            throw new BadRequestException("the period " + found.name() + " is locked");
        }
        if (!found.closed() && !found.softClosed()) {
            throw new BadRequestException("the period " + found.name() + " is not closed");
        }
        repository.reopen(id, found.id());
        audit.record("PERIOD_REOPENED sheet=" + id + " by=" + by + " period=" + found.name());
        period.set(new Period(found.id(), found.name(), found.from(), found.to(), false, null, java.util.Map.of(), java.util.Map.of(), false, found.cap(),
                repository.list(id).stream().filter(p -> p.id() == found.id()).findFirst().map(Period::personOpenings).orElse(java.util.Map.of()), false));
    }
}
